// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date this screen shows the sheet as of (yyyy-MM-dd; the `asof` search param, see features/asof), or ''. While
 *  set, every read of a sheet asks for it as it stood then (`asOf`), and every change carries it (the X-As-Of header)
 *  so the server refuses it. */
export function viewAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return /^"?(\d{4}-\d{2}-\d{2})"?$/.exec(raw)?.[1] ?? '';
}

async function send<T>(path: string, init?: RequestInit, now = false): Promise<T> {
  const asOf = now ? '' : viewAsOf();
  if (asOf !== '' && path.startsWith('/api/sheets/')) {
    if ((init?.method ?? 'GET') === 'GET') {
      path = `${path}${path.includes('?') ? '&' : '?'}asOf=${asOf}`;
    } else {
      init = { ...init, headers: { ...(init?.headers as Record<string, string>), 'X-As-Of': asOf } };
    }
  }
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

/** A read; `now` asks for the sheet as it is now, whatever the as-of date (see query/readNow). */
export function getJson<T>(path: string, now = false): Promise<T> {
  return send<T>(path, undefined, now);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { type Person } from '../people/people';
import { usePersonRowAction } from '../people/rowAction';
import { useWatches, watchesKey, type Watch } from './watch';

function WatchHead() {
  return (
    <>
      <th>Watched</th>
      <th />
    </>
  );
}

/** Whether the signed-in user watches the person, and the button that starts or stops them watching. A settle,
 *  approve or re-settle of a watched person's claim notifies each watcher (in the audit file). A refused change shows
 *  the row's error. */
function PersonWatch({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const queryClient = useQueryClient();
  const watches = useWatches(sheetId);
  const submit = useSubmitOnce();
  const rowAction = usePersonRowAction(sheetId, person.id, 'watch');
  const watched = (watches.data ?? []).some((w) => w.personId === person.id && w.user === user);
  const watch = useMutation({
    mutationFn: (on: boolean) =>
      postJson<Watch>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/watch`, { on, by: user }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: watchesKey(sheetId) }),
    onSettled: submit.end,
  });

  return (
    <>
      <td data-testid="person-watched">{watched ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="person-watch"
          disabled={watch.isPending || !watches.isSuccess}
          onClick={() => {
            if (!submit.begin()) return;
            rowAction.take();
            watch.reset();
            watch.mutate(!watched);
          }}
        >
          {watched ? 'Unwatch' : 'Watch'}
        </button>
        {watch.isError && rowAction.isLatest && <span data-testid="person-error"> Could not change watching this person.</span>}
      </td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 70, Component: WatchHead }),
  PersonRow.fill({ order: 70, Component: PersonWatch }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** That `user` watches the person `personId`. */
export type Watch = { personId: number; user: string };

export const watchesKey = (sheetId: string) => ['sheet', sheetId, 'watches'];

/** Every watch on the sheet, in the order they were started. */
export function useWatches(sheetId: string) {
  return useQuery({
    queryKey: watchesKey(sheetId),
    queryFn: () => getJson<Watch[]>(`/api/sheets/${encodeURIComponent(sheetId)}/watches`),
  });
}
