      if (r.type === 'characterData') showNode(r.target as Text, locale);
      else r.addedNodes.forEach((n) => showTree(n, locale));
    }
  });
  observer.observe(root, { subtree: true, childList: true, characterData: true });
  return () => observer.disconnect();
}
